<!-- 文件作用：个人资料、接单身份、交易统计与内置管理入口。 -->
<template><AppShell active="me" title="我的集结" subtitle="你热爱的，都值得认真对待。">
  <EmptyState v-if="!state.user" title="让每一次相遇，都有名字" detail="登录后查看订单、发布服务，建立你的玩家名片。" icon="user"><button class="btn" @click="go('/pages/login/index')">登录 / 开始体验</button></EmptyState>
  <template v-else><view class="profile-card"><view class="profile-top"><view class="profile-avatar">{{ state.user.nickname.slice(0,1) }}</view><view class="profile-name"><view>{{ state.user.nickname }}</view><text>{{ state.user.role === 'admin' ? '平台管理员' : state.user.provider_enabled ? '玩家 · 打手' : '玩家' }}</text></view><button class="profile-edit" @click="editing = !editing"><Icon name="edit" :size="18"/></button></view><view class="profile-bio">{{ state.user.bio || '写下你的游戏经历，让队友更了解你。' }}</view><view class="profile-id">PLAYER ID · {{ state.user.id }}</view></view>
    <view v-if="editing" class="panel edit-panel"><view class="field"><text class="field-label">昵称</text><input v-model="form.nickname" class="input" maxlength="24" placeholder="你的玩家昵称"/></view><view class="field"><text class="field-label">个人介绍</text><textarea v-model="form.bio" class="input" maxlength="500" placeholder="擅长什么游戏？哪些时段在线？你的服务风格是…"/></view><button class="btn" :disabled="saving" @click="saveProfile">{{ saving ? '保存中…' : '保存资料' }}</button></view>
    <view class="stats-row"><view @click="go('/pages/orders/index?role=buyer')"><text>{{ stats.buying_count || 0 }}</text><view>我的需求</view></view><view @click="go('/pages/orders/index?role=provider')"><text>{{ stats.working_count || 0 }}</text><view>接单服务</view></view><view><text>{{ stats.completed_count || 0 }}</text><view>完成订单</view></view></view>
    <view class="provider-switch panel"><view><view class="switch-label">接单身份</view><text class="hint">{{ state.user.provider_enabled ? '已开启，你可以发布服务和领取需求' : '无需俱乐部，开启后自由接单' }}</text></view><switch :key="switchVersion" :checked="state.user.provider_enabled" :color="game.primary_color" :disabled="saving" @change="toggleProvider"/></view>
    <view v-if="state.user.provider_enabled" class="earnings-panel" @click="go('/pages/orders/index?role=provider&status=completed')"><view><text class="muted">已完成订单收入</text><view class="balance">¥{{ money(stats.earnings_cents) }}</view><text class="hint">{{ state.devMode ? '测试环境统计，不是真实可提现余额' : '按已完成订单统计，退款将冲减收入' }}</text></view><Icon name="wallet" :size="30" /></view>
    <view v-if="error" class="error-box mt"><text>{{ error }}</text><button class="text-btn" @click="load">重新加载</button></view>
    <view class="menu-list"><view class="menu-item" @click="go('/pages/orders/index')"><Icon name="orders"/><view><text>我的订单</text><view>交易进度、沟通与售后</view></view><Icon name="arrow" :size="15"/></view><view class="menu-item" @click="go('/pages/clubs/index?mine=1')"><Icon name="club"/><view><text>我的俱乐部</text><view>创建俱乐部、挂靠与成员管理</view></view><Icon name="arrow" :size="15"/></view><view class="menu-item" @click="go('/pages/worker/index')"><Icon name="work"/><view><text>打手工作台</text><view>服务管理与公开需求大厅</view></view><Icon name="arrow" :size="15"/></view><view v-if="state.user.role === 'admin'" class="menu-item admin-entry" @click="go('/pages/admin/index')"><Icon name="settings"/><view><text>平台管理中心</text><view>所有数据、审核、主题与订单纠纷</view></view><Icon name="arrow" :size="15"/></view><view v-if="state.devMode" class="menu-item" @click="go('/pages/login/index')"><Icon name="refresh"/><view><text>切换体验身份</text><view>本地验证玩家、打手与两类管理员</view></view><Icon name="arrow" :size="15"/></view></view>
    <view class="notice mt"><view class="rules-title">一起维护有信任的游戏社区</view><text>不提供外挂、账号交易或违法服务。拒绝私下转账。所有交付和争议材料请通过订单聊天室保存。</text></view><button class="logout-button" :disabled="saving" @click="signOut"><Icon name="logout" :size="16"/>退出登录</button>
  </template>
</AppShell></template>
<script setup>
import { ref, reactive } from 'vue'
import { onShow } from '@dcloudio/uni-app'
import AppShell from '../../components/AppShell.vue'
import EmptyState from '../../components/EmptyState.vue'
import Icon from '../../components/Icon.vue'
import { state, game, init, refreshMe, logout } from '../../lib/store'
import { api } from '../../lib/api'
import { money, go, notify } from '../../lib/format'
const switchVersion = ref(0)
const stats = ref({}), editing = ref(false), saving = ref(false), error = ref(''), form = reactive({ nickname: '', bio: '' })
/** 读取最新个人资料与订单汇总，页面返回时同步变化。 */
async function load() { error.value = ''; try { await init(); if (!state.user) return; await refreshMe(); form.nickname = state.user.nickname || ''; form.bio = state.user.bio || ''; stats.value = await api('/me/stats') || {} } catch (err) { error.value = err.message } }
/** 保存可编辑资料，不提交角色或状态等权限字段。 */
async function saveProfile() { if (!form.nickname.trim()) return notify('请填写昵称'); if (saving.value) return; saving.value = true; try { state.user = await api('/me', 'PATCH', { nickname: form.nickname.trim(), bio: form.bio.trim(), provider_enabled: state.user.provider_enabled }); editing.value = false; notify('资料已保存') } catch (err) { notify(err) } finally { saving.value = false } }
/** 开启或关闭接单身份，保留已存在订单的处理能力。 */
async function toggleProvider(event) { if (saving.value) return; const enabled = event.detail.value; if (enabled && !state.user.bio?.trim()) { editing.value = true; notify('请先填写个人介绍并保存'); switchVersion.value++; return } saving.value = true; try { state.user = await api('/me', 'PATCH', { nickname: state.user.nickname, bio: state.user.bio, provider_enabled: enabled }); notify(enabled ? '接单身份已开启' : '接单身份已关闭') } catch (err) { notify(err) } finally { saving.value = false; switchVersion.value++ } }
/** 撤销登录会话并恢复访客界面。 */
async function signOut() { if (saving.value) return; saving.value = true; try { await logout(); stats.value = {}; editing.value = false; notify('已退出登录') } catch (err) { notify(err) } finally { saving.value = false } }
onShow(load)
</script>
<style scoped>.profile-card{padding:23px;background:var(--surface);border:1px solid rgba(255,255,255,.09);border-radius:17px}.profile-top{display:flex;align-items:center;gap:14px}.profile-avatar{width:56px;height:56px;border-radius:15px;background:var(--accent);color:#082314;font-size:27px;font-weight:750;text-align:center;line-height:56px}.profile-name{flex:1}.profile-name>view{font-size:20px;font-weight:750}.profile-name>text{font-size:10px;color:var(--accent);margin-top:4px;display:block}.profile-edit{border:1px solid rgba(255,255,255,.09);width:32px;height:32px;padding:0;border-radius:50%;line-height:30px;background:none;color:#98afa1}.profile-bio{font-size:12px;color:#98afa0;line-height:1.8;margin-top:18px;white-space:pre-wrap}.profile-id{font-size:8px;letter-spacing:1.2px;color:#526e5d;padding-top:14px;border-top:1px solid rgba(255,255,255,.07);margin-top:17px}.edit-panel{margin-top:16px}.stats-row{display:flex;justify-content:space-around;margin:24px 0}.stats-row>view{text-align:center;flex:1;border-right:1px solid rgba(255,255,255,.08)}.stats-row>view:last-child{border:0}.stats-row>view>text{font-size:25px;font-weight:750}.stats-row>view>view{font-size:10px;color:#7c9687;margin-top:4px}.provider-switch{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:17px}.switch-label{font-size:14px;font-weight:650;margin-bottom:3px}.provider-switch switch{transform:scale(.8);transform-origin:right center}.earnings-panel{display:flex;align-items:center;justify-content:space-between;padding:20px 17px;border:1px solid rgba(255,255,255,.08);border-radius:13px;margin-top:13px;color:var(--accent)}.balance{margin:5px 0}.menu-list{border:1px solid rgba(255,255,255,.08);border-radius:14px;margin-top:25px;background:var(--surface);padding:0 17px}.menu-item{display:flex;align-items:center;gap:13px;padding:18px 0;border-bottom:1px solid rgba(255,255,255,.07);color:#a5bdae}.menu-item:last-child{border:0}.menu-item>view{flex:1}.menu-item>view>text{font-size:13px;font-weight:650;color:var(--text)}.menu-item>view>view{font-size:9px;color:#799484;margin-top:4px}.admin-entry{color:var(--accent)}.rules-title{color:#b5c6b9;font-size:11px;font-weight:650;margin-bottom:6px}.logout-button{display:flex;align-items:center;justify-content:center;gap:8px;background:none;border:0;color:#7b9686;margin:25px 0 0;width:100%;font-size:12px;line-height:30px}</style>
